import {hearButton} from './play-media.mjs';
import {learningInvitations} from './learning-invitations.mjs';
import {habitatPlaces,habitatReasons,habitatPlace,habitatWelcome,habitatExplanation,habitatConclusion,habitatMatch,habitatParcel} from './living-content.mjs';
import {livingVisit,hasLivingRecord,searchReady,startLiving,selectLivingPlace,inspectLiving,chooseLiving,compareLiving,helpLiving,audioLiving,findLivingParcel,carryLivingParcel} from './living-core.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(attr,text,cls='secondary',disabled=false)=>`<button type="button" class="${cls}" ${attr} ${disabled?'disabled':''}>${text}</button>`;
const hear=(text,label)=>hearButton(text,label).replace('data-speak=','data-living-audio data-speak=');
const leaf=(x,y)=>`<path d="M${x} ${y}q-30-22-36 5 20 18 36-5q25-25 35-2-15 20-35 2" fill="#8f9c62" stroke="#627a51" stroke-width="2"/>`;
function snail(){return '<g transform="translate(196 154)"><path d="M-35 26Q-12 9 17 22l19-13v25H-36Z" fill="#b4bb94" stroke="#52675e" stroke-width="2"/><circle cx="-3" cy="12" r="23" fill="#d6b77d" stroke="#75593c" stroke-width="3"/><path d="M-14 18q-12-17 6-23 20-5 19 13-1 13-13 7-6-4 1-8" fill="none" stroke="#75593c" stroke-width="3"/><path d="M29 16l-1-18m8 13 9-13" stroke="#52675e" stroke-width="3"/><circle cx="28" cy="-2" r="3" fill="#183f39"/><circle cx="45" cy="-2" r="3" fill="#183f39"/></g>';}
export function habitatArt(id,inspected=false,found=false){
 let art,alt;
 if(id==='sunny'){
  alt=inspected?'Sunlight on open ground. The dirt is dry, with nothing overhead.':'A sunny garden patch. Inspect it to look more closely.';
  art='<circle cx="285" cy="45" r="27" fill="#e9b84a"/><path d="M285 7v-7m0 90v-11m-42-34h-12m96 0h-12m-60-30-9-9m60 60 9 9" stroke="#e9b84a" stroke-width="4"/><path d="M12 156Q140 114 348 158V220H12Z" fill="#d6b77d"/><path d="M67 163l15 12-7 15m7-15 18-5m108-7-12 17 13 12m-13-12-18-2" fill="none" stroke="#a37f50" stroke-width="3"/>'+leaf(142,178);
 }else if(id==='log'){
  alt=inspected?'Cutaway beneath a log: shade and damp fallen leaves on land.'+(found?' An illustrated land snail rests nearby; a sealed café parcel sits on a separate stone.':''):'A log resting above fallen leaves. Inspect its underside.';
  art='<path d="M10 168Q160 131 350 172V220H10Z" fill="#b8c5a4"/><path d="M42 86Q170 60 281 89V149Q155 116 42 146Z" fill="#866544" stroke="#624d36" stroke-width="3"/><ellipse cx="282" cy="119" rx="28" ry="32" fill="#d6b77d" stroke="#624d36" stroke-width="3"/><ellipse cx="282" cy="119" rx="16" ry="21" fill="none" stroke="#a37f50" stroke-width="3"/><path d="M69 99l47-10m28 37 47-10m28-18 23 5" stroke="#624d36" stroke-width="3"/>'+(inspected?'<path d="M52 149Q156 124 259 148L259 190H52Z" fill="#52675e" opacity=".25"/>'+leaf(97,174)+leaf(155,190)+'<path d="M120 140q-11 15 0 15t0-15m65 5q-11 15 0 15t0-15" fill="#729fa4"/>':leaf(110,185));
  if(found)art+=snail()+'<ellipse cx="315" cy="198" rx="36" ry="12" fill="#aab1a2"/><rect x="295" y="153" width="40" height="39" rx="3" fill="#e9b84a" stroke="#75593c" stroke-width="2"/><path d="M315 154v38m-20-22h40" stroke="#fff8e4" stroke-width="4"/>';
 }else{
  alt=inspected?'A close-up below the pond surface, with water above and around a plant under the water. The bank is outside this close-up.':'A pond close-up. Inspect the spot below its surface.';
  art='<path d="M10 65Q95 50 180 65T350 65V220H10Z" fill="#abc4da"/><path d="M10 65Q95 50 180 65T350 65" fill="none" stroke="#397958" stroke-width="3"/><path d="M140 209Q130 160 155 110m-15 80q-40-5-34-33 30 2 34 33m5-30q37-2 35-29-28 0-35 29" fill="#8aa887" stroke="#397958" stroke-width="3"/><circle cx="235" cy="115" r="8" fill="none" stroke="#fff8e4" stroke-width="2"/><circle cx="248" cy="90" r="5" fill="none" stroke="#fff8e4" stroke-width="2"/>';
 }
 return `<svg class="habitat-scene" viewBox="0 0 360 225" role="img" aria-label="${alt}"><rect x="5" y="5" width="350" height="215" rx="22" fill="#eef2e6"/>${art}</svg>`;
}
function notebook(v){return `<section class="living-notebook" aria-labelledby="living-notebook-title"><h2 id="living-notebook-title">Our picture-clue notebook</h2>${v.inspected.length?`<ul>${v.inspected.map(id=>{const p=habitatPlace(id);return `<li><strong>${p.name}:</strong> ${esc(p.observation)}</li>`;}).join('')}</ul>`:'<p>Look closely at a place to keep its clues here.</p>'}<p class="tiny">These are the clues our drawings show. What could they tell us?</p></section>`;}
function comparison(v){
 const last=v.attempts.at(-1),match=last&&habitatMatch(last);
 const feedback=!last?'Try an idea, ask for help, or keep looking.':match?'Those clues fit: damp shelter on land. Compare the places before looking for the parcel.':last.place==='log'?'You chose the log. Does your reason use its damp leaves and shade?':habitatPlace(last.place).feedback;
 return `<section class="living-comparison" aria-labelledby="living-question"><h2 id="living-question" tabindex="-1">Where could a land snail rest?</h2>${hear('Where could a land snail find damp shelter? Choose a place and a reason. You can change your idea or work it out together.','Hear the question')}<fieldset><legend>Choose a place</legend><div class="living-options">${habitatPlaces.map(p=>button(`data-living-answer-place="${p.id}" aria-pressed="${v.answerPlace===p.id}"`,p.name,v.answerPlace===p.id?'secondary selected':'secondary')).join('')}</div></fieldset><fieldset><legend>Which clue goes with your idea?</legend><div class="living-options">${habitatReasons.map(r=>button(`data-living-answer-reason="${r.id}" aria-pressed="${v.answerReason===r.id}"`,r.label,v.answerReason===r.id?'secondary selected':'secondary')).join('')}</div></fieldset>${button('data-living-compare','Compare these clues','primary',!v.answerPlace||!v.answerReason)}<p class="living-feedback" role="status">${feedback}</p>${button('data-living-help','Work it out together')}${v.explained?`<div class="hint"><p>${habitatExplanation}</p>${hear(habitatExplanation,'Hear our explanation')}</div>`:''}</section>`;
}
function parcel(v,state){
 if(!v.found)return `<section class="living-search"><h2>A clue from the delivery note</h2><p>“I left a sealed parcel beside damp shelter on land.”</p>${searchReady(v)?`${button('data-living-find','Look beside the log','primary')}<p>We have clues to follow. Let’s look without disturbing the shelter.</p>`:`<p>${!v.inspected.includes('log')?'Inspect beneath the log. ':''}${!v.inspected.some(id=>id!=='log')?'Inspect a contrasting place, too. ':''}${!v.explained&&!v.matched?'Compare a place and a reason, or work it out together.':''}</p>`}</section>`;
 const full=!Number.isSafeInteger(state.cafe?.stock?.[habitatParcel.ingredientId])||state.cafe.stock[habitatParcel.ingredientId]>168;
 return `<section class="living-parcel" aria-labelledby="living-parcel-title"><h2 id="living-parcel-title" tabindex="-1">A small neighbor. A separate parcel.</h2>${habitatArt('log',true,true)}<p>In our story, a land snail rests on the leaves. The sealed café parcel sits on a stone nearby. We leave the snail and its shelter alone.</p><p class="tiny">The clues point to a good place to look. In a real garden, a snail might be somewhere else. The parcel is pretend café food, just for the café.</p><div class="living-packs" role="img" aria-label="Three sealed packs, with four Moon crunch bites marked on each">${Array.from({length:3},()=>'<span class="living-pack"><b>Moon crunch</b><i aria-hidden="true">● ●<br>● ●</i><small>4 bites</small></span>').join('')}</div><p>3 packs × 4 bites = 12 Moon crunch bites.</p>${v.carried?'<p class="living-feedback" role="status">The 12 bites are in the café cupboard. This parcel has already been carried.</p>':`${button('data-living-carry','Carry 12 bites to the café','primary',full)}${full?'<p role="status">This jar is full. It holds 180 bites. Use some Moon crunch at the café first. The sealed parcel will wait here.</p>':'<p>Your waiting guest and plate will stay just as you left them.</p>'}`}<a class="secondary" href="#cafe">${v.carried?'Back to the café':'Visit the café'}</a><section class="living-plan"><h3>Room for beds. Room for neighbors.</h3><p>${habitatConclusion}</p>${hear(habitatConclusion,'Hear a garden-planning question')}<a class="secondary" href="#wonder/many-rectangles">Return to the planting plan</a><p class="tiny">You can revisit these pictures whenever you like. This first visit has one parcel. The orchard has more to gather.</p><a class="text-button" href="#orchard">Find more ingredients</a></section></section>`;
}
export function livingPage(state){
 const v=livingVisit(state),kept=hasLivingRecord(state)&&!v;
 const header=`<header class="page-heading"><a class="back" href="#numbers"><span aria-hidden="true">←</span> Moss’s planning table</a><p class="place-name">Living Garden · First habitat investigation</p><h1>A small shelter.<br>A missing parcel.</h1><p>Moss wants room for wildlife as well as new planting beds.</p>${v?hear(habitatWelcome,'Hear our investigation'):hearButton(habitatWelcome,'Hear our investigation')}</header>`;
 const intro=`<section class="living-intro">${habitatArt('log')}<div><h2>Who else calls this garden home?</h2><p>${habitatWelcome}</p><p>No need to move a real log or visit a pond. Our pictures have the clues.</p>${button('data-living-start','Start looking together','primary')}<p class="tiny">One short investigation. Take a break whenever you like.</p></div></section>`;
 const work=v?`<nav class="living-place-tabs" aria-label="Choose a place to inspect">${habitatPlaces.map(p=>button(`data-living-place="${p.id}" aria-pressed="${v.place===p.id}"`,p.name,v.place===p.id?'secondary selected':'secondary')).join('')}</nav><section class="living-inspection" aria-labelledby="living-place-title"><div>${habitatArt(v.place,v.inspected.includes(v.place))}</div><div><h2 id="living-place-title" tabindex="-1">${habitatPlace(v.place).name}</h2>${button('data-living-inspect',v.inspected.includes(v.place)?'Look closely again':'Look closely','primary')}${v.inspected.includes(v.place)?`<p class="living-observation" role="status">${habitatPlace(v.place).observation}</p>${hear(habitatPlace(v.place).observation,'Hear this picture clue')}`:'<p>Tap to reveal this picture’s close-up clues.</p>'}</div></section>${notebook(v)}${comparison(v)}${parcel(v,state)}`:'';
 return `<div class="living-page">${header}${kept?'<section class="panel"><h2>An earlier investigation is kept</h2><p>This saved format cannot be played here. Its exact work is retained in your notes download. No new parcel will be created.</p><a class="secondary" href="#notes">Open grown-up notes</a></section>':v?work:intro}<details class="panel"><summary>Grown-ups: what this visit explores</summary><p>Compare supplied picture clues and use them to explain a possible shelter for a garden land snail. Pictures have authored conditions: not every sunny place is dry, and not every log is damp. Land snails and freshwater snails differ. The pictures are original illustrations, not a live experiment or a measurement. This is guided practice, not field identification, a fair-test experiment, or an assessment of ecological understanding. Food, interdependence, food chains, and other habitat needs are not explored here.</p><p>The first parcel is carried once per explorer. Rereading the same pictures is familiar practice; other investigations are still to come. Notes record looking, choices, explanation help and audio requests separately. They show what your child tried and what help they used, and they are not grades.</p><p>Design reference: Marble’s Habitats &amp; Basic Needs (${esc('mt_cM8YS6NXqi')}); only damp shelter is explored here, not its full evidence criteria. Science references: <a href="https://www.nhm.ac.uk/take-part/monitor-and-encourage-nature/project-archive/slime-search.html" target="_blank" rel="noopener">Natural History Museum: Slime Search</a> and <a href="https://www.rhs.org.uk/biodiversity/slugs-and-snails" target="_blank" rel="noopener">RHS: slugs and snails</a>.</p></details>${learningInvitations('living')}</div>`;
}
export function livingNotes(state){
 if(!hasLivingRecord(state))return '';
 const v=livingVisit(state);
 if(!v)return `<details class="panel"><summary>Kept Living Garden record</summary><p>Unsupported saved work; no new parcel is issued.</p><pre>${esc(JSON.stringify(state.livingGarden,null,2))}</pre></details>`;
 return `<details class="panel"><summary>Living Garden: first habitat visit</summary><p>Supplied picture clues viewed: ${v.inspected.map(id=>esc(habitatPlace(id).name)).join(', ')||'none'}.</p><p>Reasoning attempts (latest 24): ${v.attempts.map(a=>`${esc(habitatPlace(a.place).name)} + ${esc(habitatReasons.find(r=>r.id===a.reason).label)}${a.afterHelp?' (after explanation)':''}`).join('; ')||'none'}.</p><p>Explanation help: ${v.explained?'yes':'no'}. Audio requested during visit: ${v.audioRequested?'yes':'no'} (playback not inferred). Parcel found: ${v.found?'yes':'no'}. Carried: ${v.carried?'12 Moon crunch bites':'not yet'}.</p><p>Picture clues, repeat visits and choices, recorded separately. These notes show what your child tried and what help they used. They are not grades.</p></details>`;
}
export function bindLiving(state,{save,render,focus}){
 const bind=(selector,act,target)=>document.querySelectorAll(selector).forEach(b=>b.addEventListener('click',()=>{if(act(b)){save();render();if(target)focus?.(typeof target==='function'?target(b):target);}}));
 bind('[data-living-start]',()=>startLiving(state),'#living-place-title');
 bind('[data-living-place]',b=>selectLivingPlace(state,b.dataset.livingPlace),'#living-place-title');
 bind('[data-living-inspect]',()=>inspectLiving(state),'.living-observation');
 bind('[data-living-answer-place]',b=>chooseLiving(state,'answerPlace',b.dataset.livingAnswerPlace),b=>`[data-living-answer-place="${b.dataset.livingAnswerPlace}"]`);
 bind('[data-living-answer-reason]',b=>chooseLiving(state,'answerReason',b.dataset.livingAnswerReason),b=>`[data-living-answer-reason="${b.dataset.livingAnswerReason}"]`);
 bind('[data-living-compare]',()=>compareLiving(state),'.living-feedback');
 bind('[data-living-help]',()=>helpLiving(state),'.living-comparison .hint');
 bind('[data-living-find]',()=>findLivingParcel(state),'#living-parcel-title');
 bind('[data-living-carry]',()=>carryLivingParcel(state),'#living-parcel-title');
 // Do not rerender or replace the button while the existing local speech handler runs.
 document.querySelectorAll('[data-living-audio]').forEach(b=>b.addEventListener('click',()=>{if(audioLiving(state))save();}));
}
